CREATE TABLE IF NOT EXISTS "groups" ("id" bigint PRIMARY KEY NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "players" ("id" serial PRIMARY KEY NOT NULL, "telegram_user_id" bigint NOT NULL UNIQUE, "display_name" text NOT NULL, "username" text, "joined_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "group_players" ("id" serial PRIMARY KEY NOT NULL, "group_id" bigint NOT NULL REFERENCES "groups"("id"), "player_id" integer NOT NULL REFERENCES "players"("id"), "active" boolean DEFAULT true NOT NULL, "joined_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "group_players_group_player_unique" ON "group_players" ("group_id", "player_id");
CREATE TABLE IF NOT EXISTS "operator_preferences" ("group_id" bigint NOT NULL REFERENCES "groups"("id"), "operator_player_id" integer NOT NULL REFERENCES "players"("id"), "selected_target_player_id" integer NOT NULL REFERENCES "players"("id"), "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "operator_preferences_unique" ON "operator_preferences" ("group_id", "operator_player_id");
CREATE TABLE IF NOT EXISTS "completion_batches" ("id" serial PRIMARY KEY NOT NULL, "group_id" bigint NOT NULL REFERENCES "groups"("id"), "target_player_id" integer NOT NULL REFERENCES "players"("id"), "completed_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "assignments" ("id" serial PRIMARY KEY NOT NULL, "group_id" bigint NOT NULL REFERENCES "groups"("id"), "target_player_id" integer NOT NULL REFERENCES "players"("id"), "operator_player_id" integer NOT NULL REFERENCES "players"("id"), "exercise_key" text NOT NULL, "measurement" text NOT NULL, "amount" integer NOT NULL, "dice_result" integer NOT NULL, "game_date" date NOT NULL, "assigned_at" timestamp with time zone DEFAULT now() NOT NULL, "completed_at" timestamp with time zone, "completion_batch_id" integer REFERENCES "completion_batches"("id"), "undone_at" timestamp with time zone, "undone_by_player_id" integer REFERENCES "players"("id"));
CREATE TABLE IF NOT EXISTS "daily_boards" ("id" serial PRIMARY KEY NOT NULL, "group_id" bigint NOT NULL REFERENCES "groups"("id"), "game_date" date NOT NULL, "telegram_message_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "daily_boards_group_date_unique" ON "daily_boards" ("group_id", "game_date");
CREATE TABLE IF NOT EXISTS "bot_messages" ("group_id" bigint NOT NULL REFERENCES "groups"("id"), "key" text NOT NULL, "telegram_message_id" integer, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "bot_messages_group_key_unique" ON "bot_messages" ("group_id", "key");
